package run.ikaros.music;
import java.time.Instant; import java.util.HashSet; import java.util.List; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.reactive.TransactionalOperator; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentMusicQueueService implements MusicQueueService { private final MusicQueueRepository queues; private final MusicQueueEntryRepository entries; private final MusicTrackRepository tracks; private final TransactionalOperator transaction; public PersistentMusicQueueService(MusicQueueRepository q,MusicQueueEntryRepository e,MusicTrackRepository t,TransactionalOperator tx){queues=q;entries=e;tracks=t;transaction=tx;}
 @Override public Mono<MusicQueueView> create(UUID owner,CreateMusicQueueRequest r){return Flux.fromIterable(r.trackIds()).flatMap(id->tracks.findById(id).filter(t->t.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问")))).collectList().flatMap(valid->{Instant now=Instant.now();return queues.save(new MusicQueueEntity(null,owner,false,null,MusicRepeatMode.OFF,null,now,now,null)).flatMap(q->Flux.fromIterable(valid).index().flatMap(i->entries.save(new MusicQueueEntryEntity(null,q.id(),i.getT2().id(),i.getT1().intValue(),i.getT1().intValue(),owner,now))).then(Mono.just(q)));}).map(this::view);}
 @Override public Flux<MusicQueueEntryView> entries(UUID owner,UUID id){return owned(owner,id).flatMapMany(q->entries.findAllByQueueIdOrderByActivePositionAsc(id).take(100).map(this::entryView));}
 @Override public Mono<MusicQueueEntryView> add(UUID owner,UUID queueId,AddMusicQueueEntryRequest request){return owned(owner,queueId).then(tracks.findById(request.trackId()).filter(t->t.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Track 不存在或无权访问")))).flatMap(track->entries.findAllByQueueIdOrderByActivePositionAsc(queueId).map(MusicQueueEntryEntity::activePosition).reduce(-1,Math::max).flatMap(position->entries.save(new MusicQueueEntryEntity(null,queueId,track.id(),position+1,position+1,owner,Instant.now())))).map(this::entryView);}
 @Override public Mono<MusicQueueView> reorder(UUID owner,UUID queueId,List<UUID> entryIds,long expectedVersion){Mono<MusicQueueView> operation=owned(owner,queueId).flatMap(queue->{long version=queue.version()==null?0:queue.version();if(version!=expectedVersion)return Mono.error(new ConflictException("Queue 版本冲突"));return entries.findAllByQueueIdOrderByActivePositionAsc(queueId).take(100).collectList().flatMap(current->{if(current.size()!=entryIds.size()||!new HashSet<>(current.stream().map(MusicQueueEntryEntity::id).toList()).equals(new HashSet<>(entryIds)))return Mono.error(new ConflictException("提交的队列项与当前队列不一致"));List<MusicQueueEntryEntity> reordered=entryIds.stream().map(id->current.stream().filter(item->item.id().equals(id)).findFirst().orElseThrow()).map(item->new MusicQueueEntryEntity(item.id(),item.queueId(),item.trackId(),item.basePosition(),entryIds.indexOf(item.id()),item.insertedBy(),item.createdAt())).toList();return Flux.fromIterable(reordered).concatMap(entries::save).then(queues.save(new MusicQueueEntity(queue.id(),queue.ownerId(),queue.shuffleEnabled(),queue.shuffleSeed(),queue.repeatMode(),queue.currentEntryId(),queue.createdAt(),Instant.now(),queue.version()))).map(this::view);});});return transaction.transactional(operation);}
 @Override public Mono<MusicQueueView> policy(UUID owner,UUID id,UpdateMusicQueuePolicyRequest r){return owned(owner,id).flatMap(q->{long v=q.version()==null?0:q.version();if(v!=r.expectedVersion())return Mono.error(new ConflictException("Queue 版本冲突"));Long seed=r.shuffleEnabled()?(q.shuffleSeed()==null?System.nanoTime():q.shuffleSeed()):q.shuffleSeed();return queues.save(new MusicQueueEntity(q.id(),q.ownerId(),r.shuffleEnabled(),seed,r.repeatMode(),q.currentEntryId(),q.createdAt(),Instant.now(),q.version()));}).map(this::view);}
 @Override public Mono<Void> remove(UUID owner,UUID entryId){return entries.findById(entryId).switchIfEmpty(Mono.error(new NotFoundException("Queue Entry 不存在"))).flatMap(e->owned(owner,e.queueId()).then(entries.delete(e)));}
 private Mono<MusicQueueEntity> owned(UUID o,UUID id){return queues.findById(id).filter(q->q.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Queue 不存在或无权访问")));} private MusicQueueView view(MusicQueueEntity q){return new MusicQueueView(q.id(),q.shuffleEnabled(),q.repeatMode(),q.currentEntryId(),q.updatedAt(),q.version()==null?0:q.version());} private MusicQueueEntryView entryView(MusicQueueEntryEntity e){return new MusicQueueEntryView(e.id(),e.queueId(),e.trackId(),e.basePosition(),e.activePosition());}
}
